describe('Responsive Modal Test', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.get('.open-modal-button').click(); // Adjust selector to open the modal
    });

    it('should display the modal correctly on mobile screen sizes', () => {
        cy.viewport('iphone-6'); // Set viewport to mobile size
        cy.get('.modal').should('be.visible');
        cy.get('.modal').should('have.css', 'width').and('match', /100%/);
        cy.get('.modal-content').should('have.css', 'padding').and('match', /16px/);
    });

    it('should close the modal when the close button is clicked', () => {
        cy.viewport('iphone-6'); // Set viewport to mobile size
        cy.get('.close-modal-button').click(); // Adjust selector for close button
        cy.get('.modal').should('not.be.visible');
    });
});
